 "content": "def transform(grid):
    """Fill the vertical overlap of matching-color horizontal bars above a 2-bar."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    separator = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if separator is None:
        return out
    top = grid[0]
    bottom = grid[-1]
    for color in set(top) - {0, 2}:
        cols = [c for c in range(w) if top[c] == color and bottom[c] == color]
        for c in cols:
            for r in range(1, separator):
                if out[r][c] == 0:
                    out[r][c] = 4
    return out
